.np-menubar,
[data-np-menubar] {
  --np-menubar-height: 2rem;
  --np-menubar-padding: 3px;
  --np-menubar-gap: calc(var(--np-spacing) * 0.5);
  --np-menubar-radius: var(--np-radius-lg);
  --np-menubar-bg: var(--np-background);
  --np-menubar-border-color: var(--np-border);
  --np-menubar-trigger-radius: var(--np-radius-sm);
  --np-menubar-trigger-px: calc(var(--np-spacing) * 1.5);
  --np-menubar-trigger-py: 2px;
  --np-menubar-trigger-bg: var(--np-muted);

  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--np-menubar-gap);
  width: fit-content;
  max-width: 100%;
  height: var(--np-menubar-height);
  padding: var(--np-menubar-padding);
  border: 1px solid var(--np-menubar-border-color);
  border-radius: var(--np-menubar-radius);
  background-color: var(--np-menubar-bg);
}

.np-menubar-menu,
[data-np-menubar-menu] {
  position: relative;
  display: flex;
}

.np-menubar-trigger,
[data-np-menubar-trigger] {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  margin: 0;
  padding: var(--np-menubar-trigger-py) var(--np-menubar-trigger-px);
  border: 0;
  border-radius: var(--np-menubar-trigger-radius);
  background-color: transparent;
  color: inherit;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.25rem;
  white-space: nowrap;
  outline: none;
  cursor: default;
  user-select: none;
  transition:
    background-color 150ms ease,
    box-shadow 150ms ease;
}

:is(.np-menubar-trigger, [data-np-menubar-trigger]):hover,
:is(.np-menubar-trigger, [data-np-menubar-trigger]):is(
  [aria-expanded="true"],
  [data-popup-open]
) {
  background-color: var(--np-menubar-trigger-bg);
}

:is(.np-menubar-trigger, [data-np-menubar-trigger]):focus-visible {
  background-color: var(--np-menubar-trigger-bg);
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

:is(.np-menubar-trigger, [data-np-menubar-trigger]):is(
  :disabled,
  [aria-disabled="true"],
  [data-disabled]
) {
  opacity: 0.5;
  pointer-events: none;
}

.np-menubar-positioner,
[data-np-menubar-positioner] {
  z-index: 50;
  outline: none;
}

.np-menubar-content,
[data-np-menubar-content] {
  --np-menubar-min-width: 9rem;
  --np-menubar-content-radius: var(--np-radius-lg);
  --np-menubar-content-bg: var(--np-popover, var(--np-background));
  --np-menubar-content-fg: var(--np-popover-foreground, var(--np-foreground));
  --np-menubar-content-padding: calc(var(--np-spacing) * 1);
  --np-menubar-content-shadow:
    var(--np-shadow-md),
    0 0 0 1px color-mix(in oklab, var(--np-foreground) 10%, transparent);
  --np-menubar-item-fg: var(--np-menubar-content-fg);
  --np-menubar-item-radius: var(--np-radius-md);
  --np-menubar-item-px: calc(var(--np-spacing) * 1.5);
  --np-menubar-item-py: calc(var(--np-spacing) * 1);
  --np-menubar-item-gap: calc(var(--np-spacing) * 1.5);
  --np-menubar-inset: calc(var(--np-spacing) * 7);
  --np-menubar-icon-size: 1rem;
  --np-menubar-highlight-bg: var(--np-accent);
  --np-menubar-highlight-fg: var(--np-accent-foreground);
  --np-menubar-destructive-highlight: color-mix(
    in oklch,
    var(--np-destructive) 10%,
    transparent
  );
  --np-menubar-duration: 100ms;
  --np-menubar-side-offset: 8px;
  --np-menubar-align-offset: -4px;

  box-sizing: border-box;
  min-width: var(--np-menubar-min-width);
  margin: 0;
  padding: var(--np-menubar-content-padding);
  border-radius: var(--np-menubar-content-radius);
  background-color: var(--np-menubar-content-bg);
  color: var(--np-menubar-content-fg);
  box-shadow: var(--np-menubar-content-shadow);
  outline: none;
  transform-origin: var(--transform-origin, top left);
  transition:
    opacity var(--np-menubar-duration) ease,
    transform var(--np-menubar-duration) ease;
}

:is(.np-menubar-content, [data-np-menubar-content])[data-starting-style],
:is(.np-menubar-content, [data-np-menubar-content])[data-ending-style] {
  opacity: 0;
  transform: scale(0.95);
}

@starting-style {
  :is(.np-menubar-content, [data-np-menubar-content]):not([hidden]) {
    opacity: 0;
    transform: scale(0.95);
  }
}

:is(.np-menubar-menu, [data-np-menubar-menu])
  > :is(.np-menubar-content, [data-np-menubar-content]) {
  position: absolute;
  z-index: 50;
  inset-block-start: calc(100% + var(--np-menubar-side-offset));
  inset-inline-start: var(--np-menubar-align-offset);
}

.np-menubar-sub,
[data-np-menubar-sub] {
  position: relative;
}

:is(.np-menubar-sub, [data-np-menubar-sub])
  > :is(.np-menubar-sub-content, [data-np-menubar-sub-content]) {
  position: absolute;
  z-index: 50;
  inset-block-start: calc(var(--np-spacing) * -1);
  inset-inline-start: 100%;
}

:is(.np-menubar-content, [data-np-menubar-content])[hidden] {
  display: none;
}

:is(
  .np-menubar-item,
  .np-menubar-checkbox-item,
  .np-menubar-radio-item,
  .np-menubar-sub-trigger,
  [data-np-menubar-item],
  [data-np-menubar-checkbox-item],
  [data-np-menubar-radio-item],
  [data-np-menubar-sub-trigger]
) {
  box-sizing: border-box;
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--np-menubar-item-gap);
  padding: var(--np-menubar-item-py) var(--np-menubar-item-px);
  border-radius: var(--np-menubar-item-radius);
  color: var(--np-menubar-item-fg);
  font-size: 0.875rem;
  line-height: 1.25rem;
  outline: none;
  cursor: default;
  user-select: none;
}

:is(
  .np-menubar-checkbox-item,
  .np-menubar-radio-item,
  [data-np-menubar-checkbox-item],
  [data-np-menubar-radio-item]
) {
  padding-inline-end: calc(var(--np-spacing) * 8);
}

:is(
  .np-menubar-item,
  .np-menubar-checkbox-item,
  .np-menubar-radio-item,
  .np-menubar-sub-trigger,
  [data-np-menubar-item],
  [data-np-menubar-checkbox-item],
  [data-np-menubar-radio-item],
  [data-np-menubar-sub-trigger]
):is(:focus, [data-highlighted]),
:is(.np-menubar-sub-trigger, [data-np-menubar-sub-trigger]):is(
  [aria-expanded="true"],
  [data-popup-open]
) {
  background-color: var(--np-menubar-highlight-bg);
  color: var(--np-menubar-highlight-fg);
}

:is(
  .np-menubar-item,
  .np-menubar-checkbox-item,
  .np-menubar-radio-item,
  .np-menubar-sub-trigger,
  [data-np-menubar-item],
  [data-np-menubar-checkbox-item],
  [data-np-menubar-radio-item],
  [data-np-menubar-sub-trigger]
):is(.np-menubar-inset, [data-inset]),
:is(.np-menubar-label, [data-np-menubar-label]):is(
  .np-menubar-inset,
  [data-inset]
) {
  padding-inline-start: var(--np-menubar-inset);
}

:is(
  .np-menubar-item,
  .np-menubar-checkbox-item,
  .np-menubar-radio-item,
  .np-menubar-sub-trigger,
  [data-np-menubar-item],
  [data-np-menubar-checkbox-item],
  [data-np-menubar-radio-item],
  [data-np-menubar-sub-trigger]
):is([aria-disabled="true"], [data-disabled]) {
  opacity: 0.5;
  pointer-events: none;
}

:is(
    .np-menubar-item,
    .np-menubar-checkbox-item,
    .np-menubar-radio-item,
    .np-menubar-sub-trigger,
    [data-np-menubar-item],
    [data-np-menubar-checkbox-item],
    [data-np-menubar-radio-item],
    [data-np-menubar-sub-trigger]
  )
  svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is(
    .np-menubar-item,
    .np-menubar-checkbox-item,
    .np-menubar-radio-item,
    .np-menubar-sub-trigger,
    [data-np-menubar-item],
    [data-np-menubar-checkbox-item],
    [data-np-menubar-radio-item],
    [data-np-menubar-sub-trigger]
  )
  svg:not([class*="size-"]) {
  width: var(--np-menubar-icon-size);
  height: var(--np-menubar-icon-size);
}

.np-menubar-destructive,
:is(.np-menubar-item, [data-np-menubar-item])[data-variant="destructive"] {
  --np-menubar-item-fg: var(--np-destructive);
  --np-menubar-highlight-bg: var(--np-menubar-destructive-highlight);
  --np-menubar-highlight-fg: var(--np-destructive);
}

.np-menubar-item-indicator,
[data-np-menubar-item-indicator] {
  position: absolute;
  inset-inline-end: calc(var(--np-spacing) * 2);
  display: none;
  align-items: center;
  justify-content: center;
  width: var(--np-menubar-icon-size);
  height: var(--np-menubar-icon-size);
  pointer-events: none;
}

:is(
    .np-menubar-checkbox-item,
    .np-menubar-radio-item,
    [data-np-menubar-checkbox-item],
    [data-np-menubar-radio-item]
  ):is([data-checked], [aria-checked="true"])
  :is(.np-menubar-item-indicator, [data-np-menubar-item-indicator]) {
  display: flex;
}

:is(.np-menubar-sub-trigger, [data-np-menubar-sub-trigger]) > svg:last-child {
  margin-inline-start: auto;
}

[dir="rtl"]
  :is(.np-menubar-sub-trigger, [data-np-menubar-sub-trigger])
  > svg:last-child {
  transform: scaleX(-1);
}

.np-menubar-label,
[data-np-menubar-label] {
  box-sizing: border-box;
  padding: var(--np-menubar-item-py) var(--np-menubar-item-px);
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.25rem;
}

.np-menubar-separator,
[data-np-menubar-separator] {
  box-sizing: border-box;
  height: 1px;
  margin-block: var(--np-spacing);
  margin-inline: calc(var(--np-spacing) * -1);
  background-color: var(--np-border);
}

.np-menubar-shortcut,
[data-np-menubar-shortcut] {
  margin-inline-start: auto;
  color: var(--np-muted-foreground);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
}

:is(
    .np-menubar-item,
    .np-menubar-checkbox-item,
    .np-menubar-radio-item,
    .np-menubar-sub-trigger,
    [data-np-menubar-item],
    [data-np-menubar-checkbox-item],
    [data-np-menubar-radio-item],
    [data-np-menubar-sub-trigger]
  ):is(:focus, [data-highlighted])
  :is(.np-menubar-shortcut, [data-np-menubar-shortcut]) {
  color: var(--np-menubar-highlight-fg);
}

:is(.dark, [data-theme="dark"])
  :is(.np-menubar-content, [data-np-menubar-content]) {
  --np-menubar-destructive-highlight: color-mix(
    in oklch,
    var(--np-destructive) 20%,
    transparent
  );
}

@media (prefers-color-scheme: dark) {
  :root:not(.light, [data-theme="light"])
    :is(.np-menubar-content, [data-np-menubar-content]) {
    --np-menubar-destructive-highlight: color-mix(
      in oklch,
      var(--np-destructive) 20%,
      transparent
    );
  }
}

@media (prefers-reduced-motion: reduce) {
  .np-menubar-content,
  [data-np-menubar-content] {
    --np-menubar-duration: 0ms;
  }

  .np-menubar-trigger,
  [data-np-menubar-trigger] {
    transition-duration: 0ms;
  }
}

;(function () {
  "use strict"

  var BAR = ".np-menubar, [data-np-menubar]"
  var MENU = ".np-menubar-menu, [data-np-menubar-menu]"
  var TRIGGER = ".np-menubar-trigger, [data-np-menubar-trigger]"
  var CONTENT = ".np-menubar-content, [data-np-menubar-content]"
  var SUB = ".np-menubar-sub, [data-np-menubar-sub]"
  var SUB_TRIGGER = ".np-menubar-sub-trigger, [data-np-menubar-sub-trigger]"
  var SUB_CONTENT = ".np-menubar-sub-content, [data-np-menubar-sub-content]"
  var ITEM = ".np-menubar-item, [data-np-menubar-item]"
  var CHECKBOX = ".np-menubar-checkbox-item, [data-np-menubar-checkbox-item]"
  var RADIO = ".np-menubar-radio-item, [data-np-menubar-radio-item]"
  var SEPARATOR = ".np-menubar-separator, [data-np-menubar-separator]"
  var LABEL = ".np-menubar-label, [data-np-menubar-label]"
  var RADIO_GROUP =
    ".np-menubar-radio-group, [data-np-menubar-radio-group], [role='group']"
  var ANY_ITEM = [ITEM, CHECKBOX, RADIO, SUB_TRIGGER].join(", ")
  var HOVER_DELAY = 100

  var ready = new WeakSet()
  var uid = 0

  function child(el, selector) {
    return (
      Array.prototype.find.call(el.children, function (c) {
        return c.matches(selector)
      }) || null
    )
  }

  function ensureId(el, prefix) {
    if (!el.id) el.id = prefix + "-" + ++uid
    return el.id
  }

  function isDisabled(el) {
    return (
      el.getAttribute("aria-disabled") === "true" ||
      el.hasAttribute("data-disabled")
    )
  }

  function setup(bar) {
    if (ready.has(bar)) return
    var menus = Array.prototype.filter.call(bar.children, function (c) {
      return c.matches(MENU)
    })
    if (!menus.length) return
    ready.add(bar)

    var current = null
    var hoverTimer = null

    function rtl() {
      return getComputedStyle(bar).direction === "rtl"
    }
    function triggerOf(menu) {
      return child(menu, TRIGGER)
    }
    function contentOf(menu) {
      return child(menu, CONTENT)
    }
    function menuOf(el) {
      return el.closest(MENU)
    }

    // ---- ARIA wiring ------------------------------------------------------
    if (!bar.hasAttribute("role")) bar.setAttribute("role", "menubar")

    function wireContent(content, labelledBy) {
      if (!content.hasAttribute("role")) content.setAttribute("role", "menu")
      content.hidden = true
      if (labelledBy && !content.hasAttribute("aria-labelledby"))
        content.setAttribute("aria-labelledby", labelledBy)
      Array.prototype.forEach.call(
        content.querySelectorAll("*"),
        function (el) {
          if (el.closest(CONTENT) !== content) return
          if (el.matches(SEPARATOR) && !el.hasAttribute("role"))
            el.setAttribute("role", "separator")
          if (el.matches(LABEL) && !el.hasAttribute("role"))
            el.setAttribute("role", "presentation")
          if (el.matches(ANY_ITEM)) {
            var role = el.matches(CHECKBOX)
              ? "menuitemcheckbox"
              : el.matches(RADIO)
                ? "menuitemradio"
                : "menuitem"
            if (!el.hasAttribute("role")) el.setAttribute("role", role)
            el.setAttribute("tabindex", "-1")
            if (role !== "menuitem" && !el.hasAttribute("aria-checked")) {
              el.setAttribute(
                "aria-checked",
                el.hasAttribute("data-checked") ? "true" : "false"
              )
            }
            if (el.matches(SUB_TRIGGER)) {
              el.setAttribute("aria-haspopup", "menu")
              el.setAttribute("aria-expanded", "false")
              var sub = el.closest(SUB)
              var subContent = sub && child(sub, CONTENT)
              if (subContent) {
                el.setAttribute(
                  "aria-controls",
                  ensureId(subContent, "np-menubar-sub")
                )
                wireContent(subContent, ensureId(el, "np-menubar-item"))
              }
            }
          }
        }
      )
    }

    menus.forEach(function (menu, i) {
      var trigger = triggerOf(menu)
      var content = contentOf(menu)
      if (!trigger || !content) return
      trigger.setAttribute("aria-haspopup", "menu")
      trigger.setAttribute("aria-expanded", "false")
      trigger.setAttribute(
        "aria-controls",
        ensureId(content, "np-menubar-menu")
      )
      trigger.setAttribute("tabindex", i === 0 ? "0" : "-1")
      wireContent(content, ensureId(trigger, "np-menubar-trigger"))
    })

    // ---- Helpers ----------------------------------------------------------
    function itemsOf(content) {
      return Array.prototype.filter.call(
        content.querySelectorAll(ANY_ITEM),
        function (el) {
          return el.closest(CONTENT) === content && !isDisabled(el)
        }
      )
    }

    function focusItem(content, which) {
      var items = itemsOf(content)
      if (!items.length) return
      var target = which === "last" ? items[items.length - 1] : items[0]
      target.focus({ preventScroll: true })
    }

    function closeSub(sub, focusTrigger) {
      var trigger = child(sub, SUB_TRIGGER)
      var content = child(sub, CONTENT)
      if (!content || content.hidden) return
      Array.prototype.forEach.call(
        content.querySelectorAll(SUB),
        function (inner) {
          closeSub(inner, false)
        }
      )
      content.hidden = true
      if (trigger) {
        trigger.setAttribute("aria-expanded", "false")
        trigger.removeAttribute("data-popup-open")
        if (focusTrigger) trigger.focus({ preventScroll: true })
      }
    }

    function openSub(trigger, which) {
      var sub = trigger.closest(SUB)
      var content = sub && child(sub, CONTENT)
      if (!content) return
      closeSiblingSubs(trigger, sub)
      content.hidden = false
      trigger.setAttribute("aria-expanded", "true")
      if (which) focusItem(content, which)
    }

    function closeSiblingSubs(item, keep) {
      var parent = item.closest(CONTENT)
      if (!parent) return
      Array.prototype.forEach.call(
        parent.querySelectorAll(SUB),
        function (sub) {
          if (sub !== keep && sub.closest(CONTENT) === parent)
            closeSub(sub, false)
        }
      )
    }

    function closeMenu(menu, focusTrigger) {
      var trigger = triggerOf(menu)
      var content = contentOf(menu)
      Array.prototype.forEach.call(
        content.querySelectorAll(SUB),
        function (sub) {
          closeSub(sub, false)
        }
      )
      content.hidden = true
      trigger.setAttribute("aria-expanded", "false")
      if (current === menu) current = null
      if (focusTrigger) trigger.focus({ preventScroll: true })
    }

    function openMenu(menu, which) {
      if (current && current !== menu) closeMenu(current, false)
      var trigger = triggerOf(menu)
      var content = contentOf(menu)
      content.hidden = false
      trigger.setAttribute("aria-expanded", "true")
      current = menu
      menus.forEach(function (m) {
        triggerOf(m).setAttribute("tabindex", m === menu ? "0" : "-1")
      })
      if (which) focusItem(content, which)
    }

    function closeAll(focusTrigger) {
      if (current) closeMenu(current, focusTrigger)
    }

    function moveMenu(from, step, openAfter) {
      var i = (menus.indexOf(from) + step + menus.length) % menus.length
      var next = menus[i]
      if (openAfter) openMenu(next, "first")
      else triggerOf(next).focus({ preventScroll: true })
    }

    function select(item) {
      item.dispatchEvent(
        new CustomEvent("np-menubar-select", {
          bubbles: true,
          detail: { item: item },
        })
      )
    }

    // ---- Pointer ----------------------------------------------------------
    bar.addEventListener("click", function (e) {
      var trigger = e.target.closest(TRIGGER)
      if (
        trigger &&
        trigger.parentNode &&
        menus.indexOf(trigger.parentNode) !== -1
      ) {
        if (isDisabled(trigger)) return
        var menu = menuOf(trigger)
        if (current === menu) closeMenu(menu, false)
        else openMenu(menu, e.detail === 0 ? "first" : null)
        return
      }

      var item = e.target.closest(ANY_ITEM)
      if (!item || isDisabled(item) || !bar.contains(item)) return

      if (item.matches(SUB_TRIGGER)) {
        openSub(item, e.detail === 0 ? "first" : null)
        return
      }
      if (item.matches(CHECKBOX)) {
        var on = item.getAttribute("aria-checked") !== "true"
        item.setAttribute("aria-checked", String(on))
        if (on) item.setAttribute("data-checked", "")
        else item.removeAttribute("data-checked")
        select(item)
        return
      }
      if (item.matches(RADIO)) {
        var group = item.closest(RADIO_GROUP) || item.closest(CONTENT)
        Array.prototype.forEach.call(
          group.querySelectorAll(RADIO),
          function (radio) {
            radio.setAttribute("aria-checked", "false")
            radio.removeAttribute("data-checked")
          }
        )
        item.setAttribute("aria-checked", "true")
        item.setAttribute("data-checked", "")
        select(item)
        return
      }
      select(item)
      closeAll(true)
    })

    bar.addEventListener("mouseover", function (e) {
      var trigger = e.target.closest(TRIGGER)
      if (
        trigger &&
        current &&
        trigger.parentNode &&
        menus.indexOf(trigger.parentNode) !== -1
      ) {
        var menu = menuOf(trigger)
        if (menu !== current && !isDisabled(trigger)) openMenu(menu, null)
        return
      }
      var item = e.target.closest(ANY_ITEM)
      if (!item || isDisabled(item) || !bar.contains(item)) return
      item.focus({ preventScroll: true })
      clearTimeout(hoverTimer)
      if (item.matches(SUB_TRIGGER)) {
        hoverTimer = setTimeout(function () {
          openSub(item, null)
        }, HOVER_DELAY)
      } else {
        hoverTimer = setTimeout(function () {
          closeSiblingSubs(item, null)
        }, HOVER_DELAY)
      }
    })

    document.addEventListener("pointerdown", function (e) {
      if (current && !bar.contains(e.target)) closeAll(false)
    })

    // ---- Focus highlight --------------------------------------------------
    bar.addEventListener("focusin", function (e) {
      var item = e.target.closest(ANY_ITEM)
      if (item) item.setAttribute("data-highlighted", "")
      var trigger = e.target.closest(TRIGGER)
      if (trigger && menus.indexOf(trigger.parentNode) !== -1) {
        menus.forEach(function (m) {
          triggerOf(m).setAttribute(
            "tabindex",
            triggerOf(m) === trigger ? "0" : "-1"
          )
        })
      }
    })

    bar.addEventListener("focusout", function (e) {
      var item = e.target.closest(ANY_ITEM)
      if (item) item.removeAttribute("data-highlighted")
    })

    // ---- Keyboard ---------------------------------------------------------
    bar.addEventListener("keydown", function (e) {
      var forward = rtl() ? "ArrowLeft" : "ArrowRight"
      var backward = rtl() ? "ArrowRight" : "ArrowLeft"
      var key = e.key

      var trigger = e.target.closest(TRIGGER)
      if (
        trigger &&
        trigger.parentNode &&
        menus.indexOf(trigger.parentNode) !== -1
      ) {
        var menu = menuOf(trigger)
        if (key === forward) {
          e.preventDefault()
          moveMenu(menu, 1, !!current)
        } else if (key === backward) {
          e.preventDefault()
          moveMenu(menu, -1, !!current)
        } else if (key === "ArrowDown") {
          e.preventDefault()
          openMenu(menu, "first")
        } else if (key === "ArrowUp") {
          e.preventDefault()
          openMenu(menu, "last")
        } else if (key === "Home" || key === "End") {
          e.preventDefault()
          var edge = key === "Home" ? menus[0] : menus[menus.length - 1]
          if (current) openMenu(edge, "first")
          else triggerOf(edge).focus({ preventScroll: true })
        } else if (key === "Escape" && current) {
          e.preventDefault()
          closeAll(true)
        }
        return
      }

      var item = e.target.closest(ANY_ITEM)
      if (!item || !bar.contains(item)) return
      var content = item.closest(CONTENT)
      var inSub = content.matches(SUB_CONTENT)
      var items = itemsOf(content)
      var index = items.indexOf(item)

      if (key === "ArrowDown") {
        e.preventDefault()
        items[(index + 1) % items.length].focus({ preventScroll: true })
      } else if (key === "ArrowUp") {
        e.preventDefault()
        items[(index - 1 + items.length) % items.length].focus({
          preventScroll: true,
        })
      } else if (key === "Home") {
        e.preventDefault()
        items[0].focus({ preventScroll: true })
      } else if (key === "End") {
        e.preventDefault()
        items[items.length - 1].focus({ preventScroll: true })
      } else if (key === forward) {
        e.preventDefault()
        if (item.matches(SUB_TRIGGER)) openSub(item, "first")
        else if (!inSub && current) moveMenu(current, 1, true)
      } else if (key === backward) {
        e.preventDefault()
        if (inSub) closeSub(content.closest(SUB), true)
        else if (current) moveMenu(current, -1, true)
      } else if (key === "Enter" || key === " ") {
        e.preventDefault()
        if (item.matches(SUB_TRIGGER)) openSub(item, "first")
        else item.click()
      } else if (key === "Escape") {
        e.preventDefault()
        closeAll(true)
      } else if (key === "Tab") {
        closeAll(false)
      } else if (key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        var ch = key.toLowerCase()
        for (var step = 1; step <= items.length; step++) {
          var candidate = items[(index + step) % items.length]
          if (candidate.textContent.trim().toLowerCase().indexOf(ch) === 0) {
            candidate.focus({ preventScroll: true })
            break
          }
        }
      }
    })
  }

  function init(root) {
    var scope = root || document
    if (scope.matches && scope.matches(BAR)) setup(scope)
    scope.querySelectorAll(BAR).forEach(setup)
  }

  window.NepuiMenubar = { init: init }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      init()
    })
  } else {
    init()
  }
})()
